import os, re, json

RLM_SESSION_DIR = os.environ.get('RLM_SESSION_DIR', '')
if RLM_SESSION_DIR:
    sessions_path = os.path.join(RLM_SESSION_DIR, '../../sessions')
    session_file = sessions_path + '/' + os.path.basename(RLM_SESSION_DIR) + '.jsonl'

    try:
        with open(session_file, 'r') as f:
            content = f.read()

        demos = {}
        for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n(.*?)(?=\n[0-9a-zA-Z ]{20,}|\Z)', content, re.DOTALL):
            key = m.group(1)
            h, w = int(m.group(2)), int(m.group(3))
            rows_str = m.group(4).strip()
            rows = [row.split() for row in rows_str.split('\n') if row.strip()]
            if len(rows) == h and all(len(row) == w for row in rows):
                demos[key] = [[int(x) for x in row] for row in rows]

        print("Loaded keys:", sorted(demos.keys()))
        for k in demos:
            print(f"\n{key} ({len(demos[k][0])}x{len(demos[k])}):")
            print(json.dumps(demos[k], indent=2))
    except Exception as e:
        print(f"Error loading files: {e}")
